
/**
 * @file constraint_groups.h
 * @brief Declares the container that categorises model constraint equations.
 *
 * Groups of constraints are collected during model assembly and can then be
 * reported or flattened into a single list for solver consumption.
 *
 * @see src/constraints/constraint_groups.cpp
 */

#pragma once

#include "types/equation.h"
#include "../core/types_eig.h"

namespace fem {
namespace constraint {

/**
 * @struct ConstraintGroups
 * @brief Organises constraint equations according to their origin.
 *
 * Constraint equations are generated by different model features, including
 * supports, connectors, multi-point constraints, couplings and rigid bodies.
 * This structure keeps these equations separated by their physical or logical
 * origin while providing a unified interface for subsequent processing.
 *
 * The grouped representation serves three purposes:
 * - Combining all equations into a single system for constraint enforcement.
 * - Preserving their origin for diagnostics and reaction force recovery.
 * - Identifying nodal degrees of freedom affected by support conditions.
 *
 * ConstraintGroups does not enforce or solve the constraints. It only stores
 * and organises the equations generated during model assembly.
 */
struct ConstraintGroups {
    // Constraint equations grouped by their physical or logical origin.
    // Supports describe prescribed boundary conditions, while the remaining
    // groups represent relationships between degrees of freedom. The 'others'
    // group contains manually specified or otherwise uncategorised equations.
    Equations supports;
    Equations connectors;
    Equations mpcs;
    Equations couplings;
    Equations ties;
    Equations rbms;
    Equations others;

    // Combine all constraint groups into a single equation list.
    // The original group ordering is preserved, and the source groups remain
    // unchanged so their origin information is available for later processing.
    Equations flatten() const;

    // Construct a boolean nodal mask from the support equations.
    // Entries are marked where support equations reference active structural
    // DOFs. All other entries remain false. The mask is primarily used to
    // restrict reaction force output to DOFs associated with supports.
    BooleanMatrix support_mask(const SystemDofIds& dofs) const;

    // Write a detailed overview of all constraint groups to the logger.
    // Reports the number of equations in each group and formats individual
    // equations for inspection and debugging.
    void report() const;
};

} // namespace constraint
} // namespace fem
